const table = document.querySelector('[aria-labelledby="c9"]') || document.querySelector('table');
// Find all data points in the price graph
const monthCells = document.querySelectorAll('g[role="row"]');
const allCells = document.querySelectorAll('[role="rowheader"], [role="gridcell"]');
const headers = [];
const result = [];

// Try to extract from SVG
const svgs = document.querySelectorAll('svg');
let priceGraphSvg = null;
svgs.forEach(svg => {
  const ariaLabel = svg.getAttribute('aria-label');
  if (ariaLabel && (ariaLabel.includes('价格') || ariaLabel.includes('price') || ariaLabel.includes('Price') || ariaLabel.includes('fare'))) {
    priceGraphSvg = svg;
  }
});

return {
  svgLabels: Array.from(svgs).map(s => s.getAttribute('aria-label')).filter(Boolean),
  svgCount: svgs.length
};

// Try to find the price graph data
const result = {};

// Get all SVG groups with specific identifiers
const svgGroups = document.querySelectorAll('g[aria-label]');
result.svgGroups = [];
svgGroups.forEach(g => {
  const label = g.getAttribute('aria-label');
  if (label && (label.includes('$') || label.includes('US$') || /\d/.test(label))) {
    result.svgGroups.push(label);
  }
});

// Get all elements with role=row or gridcell
const gridCells = document.querySelectorAll('[role="rowheader"], [role="gridcell"]');
result.gridCells = [];
gridCells.forEach(c => {
  const label = c.getAttribute('aria-label');
  const text = c.innerText;
  if (text && (text.includes('月') || text.includes('$') || text.includes('US$'))) {
    result.gridCells.push({label, text: text.substring(0, 100)});
  }
});

return result;

// Get the price graph SVG content
const graphTable = document.querySelector('table[aria-labelledby="c9"]');
if (!graphTable) return {error: 'no table found'};

// Look at all g elements inside the table
const groups = graphTable.querySelectorAll('g[aria-label]');
const result = {table: true, groups: [], childCount: graphTable.children.length};

// Also check for any data attributes or aria-labels
const allElements = graphTable.querySelectorAll('*');
result.allElements = [];
allElements.forEach(el => {
  if (el.getAttribute('aria-label')) {
    result.allElements.push({
      tag: el.tagName,
      label: el.getAttribute('aria-label'),
      role: el.getAttribute('role')
    });
  }
});

return result;

// Find the price graph (when is the fare lowest)
const headings = document.querySelectorAll('h1, h2, h3, [role="heading"]');
const priceGraphs = [];
headings.forEach(h => {
  if (h.innerText && (h.innerText.includes('票价') || h.innerText.includes('price'))) {
    priceGraphs.push(h.innerText);
  }
});

// Look at the table with view:bejgd
const allSvgs = document.querySelectorAll('svg[aria-label]');
const svgInfo = [];
allSvgs.forEach(svg => {
  const label = svg.getAttribute('aria-label');
  if (label) {
    svgInfo.push({label: label.substring(0, 100), width: svg.clientWidth, height: svg.clientHeight});
  }
});

// Find any element mentioning 'cheapest' or 'most expensive' or month
const allElementsWithText = [];
const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
let node;
while (node = walker.nextNode()) {
  const text = node.nodeValue.trim();
  if (text && (text.includes('十一月') || text.includes('七月') || text.includes('US$') || text.includes('month') || text.includes('Price') || text.includes('最低') || text.includes('最高'))) {
    if (text.length < 200) {
      allElementsWithText.push(text);
    }
  }
}

return {priceGraphs, svgInfo: svgInfo.slice(0, 30), textElements: allElementsWithText.slice(0, 50)};

// Find all price graph data
const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
let node;
const allTexts = [];
while (node = walker.nextNode()) {
  const text = node.nodeValue.trim();
  if (text && (text.match(/US\$\d+/) || text.match(/\d+月/) || ['一月','二月','三月','四月','五月','六月','七月','八月','九月','十月','十一月','十二月'].some(m => text.includes(m)) || text.includes('价格') || text.includes('最低') || text.includes('最高'))) {
    if (text.length < 100) {
      allTexts.push(text);
    }
  }
}

return allTexts;

// Find all data points in the price graph - get elements with specific patterns
const pricePoints = [];
const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_ELEMENT);
let node;

// Find all buttons and links that mention flight prices for the graph
const links = document.querySelectorAll('a, button');
links.forEach(l => {
  const text = l.innerText;
  const ariaLabel = l.getAttribute('aria-label');
  if ((ariaLabel && ariaLabel.includes('US$') && ariaLabel.includes('起的航班')) || 
      (text && text.includes('US$') && text.includes('起的航班'))) {
    pricePoints.push({
      text: text.substring(0, 200),
      label: ariaLabel ? ariaLabel.substring(0, 200) : null
    });
  }
});

// Also try to find the SVG groups
const svgPaths = document.querySelectorAll('g[aria-roledescription]');
const svgData = [];
svgPaths.forEach(p => {
  svgData.push({
    label: p.getAttribute('aria-label'),
    role: p.getAttribute('role'),
    description: p.getAttribute('aria-roledescription')
  });
});

return {pricePoints: pricePoints.slice(0, 20), svgData: svgData.slice(0, 30)};

// Find all elements with US$ price information including hidden ones
const allElements = document.querySelectorAll('*');
const prices = [];
allElements.forEach(el => {
  const text = el.innerText;
  if (text && text.length < 30 && text.match(/^US\$\d+$/)) {
    prices.push(text);
  }
});

// Get unique prices
const uniquePrices = [...new Set(prices)];

// Look for all elements containing '起的航班' or price range
const rangeElements = [];
document.querySelectorAll('*').forEach(el => {
  const text = el.innerText;
  if (text && text.length < 50 && text.match(/US\$\d+\s*-\s*\d+/)) {
    if (el.children.length === 0) {
      rangeElements.push(text);
    }
  }
});

return {uniquePrices, rangeElements: [...new Set(rangeElements)]};
